{
  "schema_version": 1,
  "summary": "payment-svc v2.3.1 版本升级后，收单渠道 SDK 从 v1 升级至 v2，导致 /v1/charge 接口调用 acquirer-pay 时 P99 延迟激增（220ms → 9.8s）并触发大量上游超时，引发支付失败率飙升、订单创建成功率骤降及 HTTP 5xx 高发。",
  "root_cause": "payment-svc v2.3.1 中集成的收单渠道 SDK v2 存在兼容性缺陷或性能退化，致使对 acquirer-pay 的同步调用出现严重延迟与超时。",
  "evidence": [
    "08:50 完成 payment-svc v2.3.1 发布，同步升级收单渠道 SDK 从 v1 至 v2",
    "08:52 起 /v1/charge 调用 acquirer-pay 的 P99 延迟从 220ms 升至 9.8s，超时率 49%",
    "所有告警均集中于 /v1/charge 路径，错误类型统一为 'upstream timeout'",
    "payment-svc CPU/内存/连接池水位正常，排除资源瓶颈",
    "order-svc 自身无异常，其失败 100% 源于支付调用超时，证实问题位于 payment-svc → acquirer-pay 链路"
  ],
  "impact": "支付失败率 50.2%，订单创建成功率降至 51%，影响全部依赖支付的订单流程；持续约 3 分钟（08:52–08:55），覆盖高峰期初始流量。",
  "remediation": "立即回滚 payment-svc 至 v2.3.0（含收单渠道 SDK v1）；同步联系 SDK 供应商复现并修复 v2 版本超时问题；后续发布需增加全链路压测及 acquirer-pay 模拟高延迟验收。",
  "references": [
    {
      "artifact_ref": "prometheus://query?expr=histogram_quantile(0.99%2C+rate(payment_svc_acquirer_pay_latency_seconds_bucket%5B5m%5D))&start=2026-09-05T08:45:00Z&end=2026-09-05T09:00:00Z"
    },
    {
      "artifact_ref": "prometheus://query?expr=rate(payment_svc_http_requests_total%7Bcode%3D~%225..%22%2Cpath%3D%22%2Fv1%2Fcharge%22%7D%5B5m%5D)&start=2026-09-05T08:45:00Z&end=2026-09-05T09:00:00Z"
    },
    {
      "artifact_ref": "dashboard://payment-svc-release-impact-v2.3.1"
    }
  ]
}

